import mockCmsData from '../src/data/mockCmsData.js';

test('SQLite seeds once, persists saves across reopen, and preserves the public contract', t => {
  const directory = mkdtempSync(join(tmpdir(), 'wise-store-'));
  const databasePath = join(directory, 'content.sqlite');
  let store = createContentStore({ databasePath, seed: mockCmsData });
  t.after(() => { store.close(); rmSync(directory, { recursive: true, force: true }); });
  assert.deepEqual(store.read(), mockCmsData);
  const edited = structuredClone(mockCmsData);
  edited.site.tagline = 'Updated partner tagline';
  const saved = store.save(edited, 1);
  assert.equal(saved.version, 2);
  store.close();
  store = createContentStore({ databasePath, seed: mockCmsData });
  assert.equal(store.read().site.tagline, edited.site.tagline);
  assert.equal(store.readWithVersion().version, 2);
});

test('SQLite rejects a stale update without altering the winning document', t => {
  const store = createContentStore({ databasePath: ':memory:', seed: mockCmsData });
  t.after(() => store.close());
  store.save(mockCmsData, 1);
  assert.throws(() => store.save({ broken: true }, 1), error => error.status === 409);
  assert.deepEqual(store.read(), mockCmsData);
  assert.equal(store.readWithVersion().version, 2);
});